// ── Agency OS feed reader ────────────────────────────────────────────────
// Shared fail-honest reader for the operating-surface feeds generated by
// rig-gtm-studio-v2's `outbound.agency_os_feeds` (fleet lane: agency-os-feeds,
// non-outward). One reader so every route degrades the same way: a missing or
// unparseable feed returns `feed_available: false` with the regenerate command
// — never an invented zero. Pattern lifted from /api/agency/leads, the route
// that replaced a hardcoded fixture ("Sarah Chen, TechFlow SaaS") on 2026-07-31.

import { existsSync, readFileSync } from "fs";
import { join } from "path";

const GTM_STUDIO_ROOT = "/Users/rig128gb/Developer/rig-gtm-studio-v2";
const FEED_DIR = join(GTM_STUDIO_ROOT, "out", "agency");

export interface FeedEnvelope {
  feed_available: boolean;
  /** Where the numbers came from — rendered verbatim by pages. */
  _source: string;
  feed?: Record<string, any>;
  error?: string;
}

export function readAgencyFeed(filename: string): FeedEnvelope {
  const path = join(FEED_DIR, filename);
  const regen =
    `cd ${GTM_STUDIO_ROOT} && .venv/bin/python -m outbound.agency_os_feeds`;
  try {
    if (!existsSync(path)) {
      return {
        feed_available: false,
        _source: `NO DATA — ${path} not generated. Regenerate: ${regen}`,
        error: "feed missing",
      };
    }
    const feed = JSON.parse(readFileSync(path, "utf-8"));
    return {
      feed_available: true,
      _source: `${path} (generated ${feed.generated_at ?? "unknown"}) via ` +
        `outbound.agency_os_feeds [lane: agency-os-feeds]`,
      feed,
    };
  } catch (e) {
    return {
      feed_available: false,
      _source: `NO DATA — ${path} unreadable. Regenerate: ${regen}`,
      error: String(e),
    };
  }
}
